function fetchGithubCheckLogs(check, scm, owner, repo) {
    var jobIdMatch = check.details_url && check.details_url.match(/\/jobs?\/(\d+)/);
    if (jobIdMatch) {
        try {
            var rawLogs = scm ? scm.getJobLogs(jobIdMatch[1]) : github_get_job_logs({
