            if (jobLogs) out += '=== ' + (runJob.name || 'job ' + runJob.id) + ' ===\n' + jobLogs + '\n';
        });
        return out || null;
    } catch (e) {
        console.warn('Could not fetch jobs/logs for run', runIdMatch[1], ':', e.message || e);
        return null;
    }
}

