        var rawJobs = (scm && typeof scm.getWorkflowRunJobs === 'function')
            ? scm.getWorkflowRunJobs(runIdMatch[1])
            : github_get_workflow_run_jobs({
                workspace: owner, repository: repo, runId: runIdMatch[1]
            });
