  for (;;) {
    if (realpathOrSelf(dir) === canonicalRoot) candidates.push(suffix.join('/'));
    const parent = path.dirname(dir);
    if (parent === dir) return candidates; // reached the filesystem root
    suffix.unshift(path.basename(dir));
    dir = parent;
