        assert.ok(!gh.isFailedRunJob({ id: 1, conclusion: 'success' }));
        assert.ok(!gh.isFailedRunJob({ conclusion: 'failure' }), 'no id');
        assert.ok(!gh.isFailedRunJob(null));
    });

